def solve(sigma3=140.0, delta_sigma_d_f=104.0, c_eff=20.0):
    import math
    sigma3_kpa = sigma3
    q_f_kpa = delta_sigma_d_f
    c_kpa = c_eff

    def predicted_q(phi):
        s = math.sin(phi)
        return (2.0 * sigma3_kpa * s + 2.0 * c_kpa * math.cos(phi)) / (1.0 - s)
    lo = 0.0
    hi = math.radians(89.999999)
    for _ in range(100):
        mid = 0.5 * (lo + hi)
        if predicted_q(mid) < q_f_kpa:
            lo = mid
        else:
            hi = mid
    phi_rad = 0.5 * (lo + hi)
    phi_deg = math.degrees(phi_rad)
    return {'1': {'value': phi_deg, 'unit': 'degrees'}}

